<?php
defined('ABSPATH') || exit;
class CDCA_Store {
 public $db;public $p;public $clock;
 public function __construct($db=null,$prefix=null,$clock=null){global $wpdb;$this->db=$db??$wpdb;$this->p=$prefix??$this->db->prefix.'cdca_';cdca_need(preg_match('/^[a-zA-Z0-9_]+$/D',$this->p),'prefix');$this->clock=$clock??'time';}
 public function now(){return (int)call_user_func($this->clock);}
 public function query($sql){$old=$this->db->suppress_errors(true);try{$r=$this->db->query($sql);cdca_need($r!==false,'content_database');return $r;}finally{$this->db->suppress_errors($old);}}
 public function tx($f){$this->query('START TRANSACTION');try{$v=$f();$this->query('COMMIT');return $v;}catch(Throwable $e){$this->db->query('ROLLBACK');throw $e;}}
 public function read($id,$lock=false){$v=$this->db->get_row($this->db->prepare("SELECT * FROM {$this->p}jobs WHERE id=%d".($lock?' FOR UPDATE':''),$id),ARRAY_A);cdca_need(!$this->db->last_error,'content_read');cdca_need($v,'job_missing');return $v;}
 public function write($id,$data){cdca_need($this->db->update($this->p.'jobs',$data,['id'=>$id])!==false,'content_write');}
 public function event($id,$action,$from,$to,$actor){cdca_need($this->db->insert($this->p.'events',['job_id'=>$id,'action'=>$action,'old_status'=>$from,'new_status'=>$to,'actor'=>substr((string)$actor,0,64),'created'=>$this->now()])!==false,'content_audit');}
 public static function schemas($p,$charset){return [
 "CREATE TABLE {$p}jobs (id bigint unsigned NOT NULL AUTO_INCREMENT, job_key char(64) NOT NULL, topic_id char(64) NOT NULL, research_item bigint unsigned NOT NULL DEFAULT 0, source_hash char(64) NOT NULL, brief longtext NOT NULL, template varchar(24) NOT NULL, status varchar(24) NOT NULL, is_test tinyint NOT NULL DEFAULT 0, attempts int NOT NULL DEFAULT 0, next_attempt bigint NOT NULL DEFAULT 0, lease_hash char(64) NOT NULL DEFAULT '', lease_until bigint NOT NULL DEFAULT 0, worker_id varchar(32) NOT NULL DEFAULT '', revision int NOT NULL DEFAULT 1, last_error varchar(64) NOT NULL DEFAULT '', created bigint NOT NULL, updated bigint NOT NULL, PRIMARY KEY  (id), UNIQUE KEY job_key (job_key), KEY due (status,is_test,next_attempt), KEY topic (topic_id,template), KEY lease_until (lease_until)) ENGINE=InnoDB $charset;",
 "CREATE TABLE {$p}versions (id bigint unsigned NOT NULL AUTO_INCREMENT, job_id bigint unsigned NOT NULL, version int NOT NULL, submission char(64) NOT NULL, document_hash char(64) NOT NULL, document longtext NOT NULL, quality longtext NOT NULL, is_mock tinyint NOT NULL DEFAULT 1, created bigint NOT NULL, PRIMARY KEY  (id), UNIQUE KEY job_version (job_id,version), UNIQUE KEY submission (submission)) ENGINE=InnoDB $charset;",
 "CREATE TABLE {$p}events (id bigint unsigned NOT NULL AUTO_INCREMENT, job_id bigint unsigned NOT NULL, action varchar(32) NOT NULL, old_status varchar(24) NOT NULL, new_status varchar(24) NOT NULL, actor varchar(64) NOT NULL, created bigint NOT NULL, PRIMARY KEY  (id), KEY job_created (job_id,created)) ENGINE=InnoDB $charset;",
 "CREATE TABLE {$p}agents (worker_id varchar(32) NOT NULL, last_seen bigint NOT NULL, window_start bigint NOT NULL, requests int NOT NULL, PRIMARY KEY  (worker_id)) ENGINE=InnoDB $charset;"
 ];}
 public static function install(){cdca_need(cdca_stage(),'staging_only');global $wpdb;require_once ABSPATH.'wp-admin/includes/upgrade.php';$s=new self();foreach(self::schemas($s->p,$wpdb->get_charset_collate()) as $sql){dbDelta($sql);}foreach(['jobs','versions','events','agents'] as $t){cdca_need($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$wpdb->esc_like($s->p.$t)))===$s->p.$t,'content_schema');}}
 public function create($evidence,$template,$is_test,$actor){
  $brief=cdca_brief($evidence,$template,$is_test);$key=cdca_hash([$evidence['topic_id'],$template,$evidence['source_hash'],(bool)$is_test]);
  // Hold the selection lock until COMMIT; never release before a rival insert.
  $guard='cdca_select_'.substr(hash('sha256',$this->p),0,32);cdca_need((int)$this->db->get_var($this->db->prepare('SELECT GET_LOCK(%s,0)',$guard))===1,'selection_busy');
  try{return $this->tx(function()use($brief,$evidence,$template,$is_test,$actor,$key){
   $old=$this->db->get_var($this->db->prepare("SELECT id FROM {$this->p}jobs WHERE job_key=%s",$key));if($old){return (int)$old;}
    cdca_need((int)$this->db->get_var("SELECT COUNT(*) FROM {$this->p}jobs")<1000,'queue_capacity');$active=$this->db->get_var($this->db->prepare("SELECT id FROM {$this->p}jobs WHERE topic_id=%s AND template=%s AND status NOT IN ('rejected','approved') LIMIT 1",$evidence['topic_id'],$template));cdca_need(!$active,'topic_already_queued');
    cdca_need($this->db->insert($this->p.'jobs',['job_key'=>$key,'topic_id'=>$evidence['topic_id'],'research_item'=>$evidence['research_item'],'source_hash'=>$evidence['source_hash'],'brief'=>cdca_json($brief),'template'=>$template,'status'=>'selected','is_test'=>(int)$is_test,'created'=>$this->now(),'updated'=>$this->now()])!==false,'content_create');$id=(int)$this->db->insert_id;$this->event($id,'selected','','selected',$actor);return $id;
  });}finally{$this->db->get_var($this->db->prepare('SELECT RELEASE_LOCK(%s)',$guard));}
 }
 public function transition($id,$to,$revision,$actor){return $this->tx(function()use($id,$to,$revision,$actor){$j=$this->read($id,true);cdca_need((int)$j['revision']===$revision,'stale_review');cdca_need(cdca_transition($j['status'],$to),'invalid_transition');if($to==='queued'||$to==='approved'){cdca_need(cdca_research_current($j),'research_changed');}if($to==='queued'&&!(int)$j['is_test']){$brief=cdca_job_brief($j);cdca_need(($brief['sufficiency']['generation_allowed']??false)===true,'evidence_insufficient');}if($to==='queued'){cdca_need((int)$this->db->get_var($this->db->prepare("SELECT COUNT(*) FROM {$this->p}versions WHERE job_id=%d",$id))<10,'version_capacity');}
  $data=['status'=>$to,'revision'=>$revision+1,'updated'=>$this->now(),'lease_until'=>0,'lease_hash'=>'','worker_id'=>''];if($to==='queued'){$data+=['attempts'=>0,'next_attempt'=>$this->now(),'last_error'=>''];}$this->write($id,$data);$this->event($id,'human_transition',$j['status'],$to,$actor);return $this->read($id);});}
 public function recover(){
  $rows=$this->db->get_results($this->db->prepare("SELECT id FROM {$this->p}jobs WHERE status='processing' AND lease_until<%d ORDER BY id LIMIT 20",$this->now()),ARRAY_A);
  foreach($rows as $row){$this->tx(function()use($row){$j=$this->read((int)$row['id'],true);if($j['status']!=='processing'||(int)$j['lease_until']>=$this->now()){return;}$this->write((int)$j['id'],['status'=>'queued','lease_hash'=>'','lease_until'=>0,'worker_id'=>'','revision'=>(int)$j['revision']+1,'last_error'=>'worker_lease_expired','next_attempt'=>$this->now()+min(3600,60*2**(int)$j['attempts']),'updated'=>$this->now()]);$this->event((int)$j['id'],'lease_expired','processing','queued','system');});}
 }
 public function claim($worker){$this->recover();return $this->tx(function()use($worker){$j=$this->db->get_row($this->db->prepare("SELECT * FROM {$this->p}jobs WHERE status='queued' AND is_test=1 AND attempts<3 AND next_attempt<=%d ORDER BY id LIMIT 1 FOR UPDATE",$this->now()),ARRAY_A);cdca_need(!$this->db->last_error,'claim_database');if(!$j){return null;}
  // Phase 1 intentionally cannot process a real selected research item.
  cdca_need((int)$j['is_test']===1,'mock_only');$token=bin2hex(random_bytes(32));$this->write((int)$j['id'],['status'=>'processing','attempts'=>(int)$j['attempts']+1,'lease_hash'=>hash('sha256',$token),'lease_until'=>$this->now()+180,'worker_id'=>$worker,'revision'=>(int)$j['revision']+1,'last_error'=>'','updated'=>$this->now()]);$this->event((int)$j['id'],'claimed','queued','processing',$worker);return ['id'=>(int)$j['id'],'lease'=>$token,'lease_seconds'=>180,'brief'=>cdca_job_brief($j,new CDCA_Evidence_Store($this->db,$this->p,$this->clock))];});}
 public function lease($j,$worker,$token,$active=true){cdca_need(is_string($token)&&preg_match('/^[a-f0-9]{64}$/D',$token)&&hash_equals($j['lease_hash'],hash('sha256',$token))&&hash_equals($j['worker_id'],$worker),'lease_rejected');if($active){cdca_need($j['status']==='processing'&&(int)$j['lease_until']>=$this->now(),'lease_expired');}}
 public function heartbeat($id,$worker,$token){return $this->tx(function()use($id,$worker,$token){$j=$this->read($id,true);$this->lease($j,$worker,$token);cdca_need($this->now()-(int)$j['updated']<=900,'lease_budget');$this->write($id,['lease_until'=>$this->now()+180]);return ['lease_seconds'=>180];});}
 public function fail($id,$worker,$token,$code){cdca_need(in_array($code,['adapter_error','adapter_timeout','invalid_output','cancelled'],true),'failure_code');return $this->tx(function()use($id,$worker,$token,$code){$j=$this->read($id,true);$this->lease($j,$worker,$token);$this->write($id,['status'=>'queued','lease_hash'=>'','lease_until'=>0,'worker_id'=>'','last_error'=>$code,'next_attempt'=>$this->now()+min(3600,60*2**(int)$j['attempts']),'revision'=>(int)$j['revision']+1,'updated'=>$this->now()]);$this->event($id,$code,'processing','queued',$worker);return ['retry_exhausted'=>(int)$j['attempts']>=3];});}
 public function complete($id,$worker,$token,$submission,$doc){
  cdca_need(is_string($submission)&&preg_match('/^[a-f0-9]{64}$/D',$submission),'submission_id');return $this->tx(function()use($id,$worker,$token,$submission,$doc){$j=$this->read($id,true);$this->lease($j,$worker,$token,false);$hash=cdca_hash($doc);$old=$this->db->get_row($this->db->prepare("SELECT version,document_hash FROM {$this->p}versions WHERE job_id=%d AND submission=%s",$id,$submission),ARRAY_A);if($old){cdca_need(hash_equals($old['document_hash'],$hash),'submission_conflict');return ['version'=>(int)$old['version'],'idempotent'=>true,'is_mock'=>true];}
   $this->lease($j,$worker,$token);cdca_need(cdca_research_current($j),'research_changed');$effective=cdca_job_brief($j,new CDCA_Evidence_Store($this->db,$this->p,$this->clock));$quality=cdca_quality($doc,$effective);$quality['brief_schema']=$effective['schema'];$quality['brief_hash']=cdca_hash($effective);$quality['source_hash']=$j['source_hash'];$quality['enrichment_snapshot']=$effective['enrichment_snapshot']??null;$version=1+(int)$this->db->get_var($this->db->prepare("SELECT MAX(version) FROM {$this->p}versions WHERE job_id=%d",$id));cdca_need($version<=10,'version_capacity');cdca_need($this->db->insert($this->p.'versions',['job_id'=>$id,'version'=>$version,'submission'=>$submission,'document_hash'=>$hash,'document'=>cdca_json($doc),'quality'=>cdca_json($quality),'is_mock'=>1,'created'=>$this->now()])!==false,'draft_write');$this->write($id,['status'=>'draft_ready','lease_until'=>0,'revision'=>(int)$j['revision']+1,'updated'=>$this->now()]);$this->event($id,'mock_draft_saved','processing','draft_ready',$worker);return ['version'=>$version,'is_mock'=>true,'quality'=>$quality];
  });
 }
 public function rate($worker){$this->tx(function()use($worker){$this->query($this->db->prepare("INSERT IGNORE INTO {$this->p}agents (worker_id,last_seen,window_start,requests) VALUES (%s,%d,%d,0)",$worker,$this->now(),$this->now()));$a=$this->db->get_row($this->db->prepare("SELECT * FROM {$this->p}agents WHERE worker_id=%s FOR UPDATE",$worker),ARRAY_A);$count=$this->now()-(int)$a['window_start']>=60?0:(int)$a['requests'];cdca_need($count<20,'worker_rate_limit');cdca_need($this->db->update($this->p.'agents',['last_seen'=>$this->now(),'window_start'=>$count===0?$this->now():(int)$a['window_start'],'requests'=>$count+1],['worker_id'=>$worker])!==false,'agent_write');});}
}
